"""Review-only operational rules; original constructs remain authoritative."""
import json
from pathlib import Path

def amend(metrics):
    original={x['id']:x for x in json.loads((Path(__file__).parent/'original-metric-baseline.json').read_text())['metrics']}
    rules={
'M1':(['在预先规定的统一搜索预算内，未发现相关官方来源','第三次或之后的查询才首次发现相关官方来源','第二次查询才首次发现相关官方来源','首次查询第2—5条出现相关官方来源','首次查询第1条即为相关官方来源'],'试用协议每次观察前5条，最多4次查询；预算是实验条件，不是通用评分定义。查询而非调用计数，批量与并行须统一协议。首次命中后继续检索不降分，改写本身不另扣分。前序超时、列表缺失或未完成预算且未命中记待定。保存每轮全部网址与精确排名。此五档是研究约定，不是已验证量表。'),
'M3':(['取得的正文只有概述，没有相关解释或操作细节','有相关细节，但只有零散参数、片段或说明，不能组成完整解释或操作段落','有完整解释或操作段落，但完成原题所需的关键步骤、参数或约束仍缺失','原题所需主流程及其参数、前提已说明，但原题明确涉及的分支、约束或参考细节未说明完整','原题要求的解释、步骤、参数和约束均说明完整，无需另查才能补齐这些内容'],'先从原题列出需要说明的内容，禁止添加题外的穷尽要求；每项缺口附正文位置。按最高满足档判定。取不到正文记受阻，不给1分；仅导航或元数据归M2。版本选择归M4。文档内容错误另记，不能只因长而判详尽。'),
'M4':(['已取得相关官方正文，但其中没有可辨识的版本信息','出现版本信息，但不能确定应选哪版；原因是选择条件缺失或版本说明互相冲突','能排除部分版本或确定版本范围，但仍不能确定一个有明确依据的适用选择','可依据明确条件选定适用版本，但需要跨已取得的官方页面对照才能确定','在同一官方页面内即可依据明确条件选定适用版本，包括清楚的单一版本说明或支持矩阵'],'先判断版本选择是否明确，再区分已明确选择是页内完成还是跨页对照。4/5区分是可复核的组织位置代理，不能解释为实测耗时。多个版本、多个组件或支持矩阵本身不扣分。记录备选版本、选择条件、引用位置；3分须列出尚不能消除的选择。检索调用代价归M8，最终答案定版归M9。'),
'M5':(['相关独立第三方来源0条','相关独立第三方来源1—2条','相关独立第三方来源3—4条','相关独立第三方来源5条','相关独立第三方来源至少6条'],'恢复原数量阈值，统一搜索预算内对相关来源去重计数，正文取得不是计数前提。官方仓库、官方论坛按已冻结的渠道分类排除；同一内容的转载或镜像只计一次。相关性无法确定则计数区间，区间跨档则待定。另报首次发现位置和查询数，避免声称数量单独涵盖全部可发现度。'),
'M6':(['存在与可靠核对依据直接矛盾的关键说法，尚未解决','未发现已确证的关键矛盾，但关键说法没有可追溯的核对依据','有可追溯依据支持部分关键说法，其他关键说法尚未核验','全部关键说法均有可追溯依据支持，未见未解决矛盾，但缺少独立来源的交叉印证','全部关键说法均有可追溯依据支持，并获独立来源交叉印证，未见未解决矛盾'],'关键说法限于会改变操作、解释或版本判断的可核验陈述，逐条记录支持/反驳/未知。权威性依据作者身份、第一手材料或可复核实验证据，不按平台名直接给分。转载不构成独立互证；旧文只有在内容已失效时才作为反证。没有第三方材料记N/A。此五档是证据可信程度量规，尚未校准。'),
'M7':(['检索前回答没有可核验的正确任务知识，或关键主张被核对证据否定','检索前仅能给出正确概念，无法给出具体方法或解释','检索前能给出正确方法或解释片段，但关键细节需要外部资料补充','检索前能够给出正确的完整流程或解释，原题涉及的具体参数、约束仍需补充','检索前回答已准确覆盖原题所需的流程、解释、参数与约束'],'执行同题无工具回答并冻结，再独立核对其中知识正确性和完整性。回答前不能接触本轮检索内容；自评信心仅存记录，不用于计分。没有检索前回答的旧运行记缺测。该测量只能反映无检索知识表现，不能推断训练数据覆盖密度；未知正确性则待定。'),
'M9':(['最终答案未提供原题需要的版本信息','提到版本，但没有给出有依据的适用版本或范围，或关键定版与证据矛盾','部分所需组件有明确版本依据，其余仍未确定','所有所需组件均给出有依据的适用范围，但至少一项尚未定到具体版本','所有所需组件均给出有依据的具体版本，配套关系无未解决冲突'],'评价对象仅为最终答案。先固定原题实际需要定版的组件；不强制无关opset。符合证据的范围不等于答案错误，但锁定粒度低于具体版本。无版本需要记N/A；不能为提高分数随意指定版本。'),
'M10':(['没有可执行方案，只有目标描述或示意','仅有操作骨架，关键操作无法根据答案确定','有具体操作方案，但需修正错误或补充缺失内容才能执行','操作指导完整，仅需替换明确标识且有说明的用户环境参数','操作指导及适用前提明确，无需补写或修正内容即可直接执行'],'按最终答案中命令、代码、参数与前置条件判断需要补充或修改的程度。4分仅替换路径、设备号等环境值，不能包括修正内容错误。3分须指出具体缺口，2分须说明哪项关键操作无法确定。每档附答案原文引用；实际运行通过、失败、仅内容核查或未验证另行记录，不把是否运行作为4/5分界。仅内容核查不能宣称实际复现成功；证据不足记待定，纯概念任务记N/A。'),
'M11':(['原综合指数小于0.24','原综合指数至少0.24、小于0.45','原综合指数至少0.45、小于0.63','原综合指数至少0.63、小于0.80','原综合指数至少0.80'],'保留综合置信度的原评价目的与五个等级；原0.24、0.45、0.63、0.80仅列入历史对照，不作为当前有效阈值。新区间尚未确定，暂不计算新结果。原噪声OR、权重及阈值未经校准，不能视为答对概率；输入量规变化后不能直接沿用旧解释。待各分项冻结后检查合理性和敏感性，再决定是否作为探索性指数报告。M9/M10不进入原公式。')}
    for d in metrics:
        k=d['id']; o=original[k]
        d['name']=o['name'];d['definition']=o['definition'];d['purpose']=o['purpose']
        if k in rules:d['bands'],d['action']=rules[k]
        d['boundary']=d['action'];d['obs']='保存原始工具返回、引用位置、判定事实和评分理由；缺测、受阻、不适用与低分分开。'
        d['example']='以实际运行记录核对上述条件；没有证据时不构造案例替代实测。'
        d['rigor']='这是待确认的研究量规；清晰可执行不等于已验证效度。尚需对既有记录独立复评，记录分歧及原因。'
        d['own']='具体五档与阈值属于本研究操作化约定，下列文献仅支持相应测量原则，不直接验证本五档。'
        if k=='M2':
            d['bands']=['未取得可识别的目标页面内容：请求失败、拒绝访问、错误页或无返回','取得目标页面标题、导航或元数据，但没有可识别正文','只取得明确标注为摘要或摘录的正文表示，未取得直接正文返回','取得直接正文，但工具明确标注截断、缺页，或可核对的正文边界存在缺失','取得直接正文，且有可核对的全文/完整目标章节起止依据，无截断或缺页证据']
            d['action']='按每个独立官方文档的最终获取状态判定。先区分无内容、框架、摘要/摘录、直接正文，再核对直接正文是否完整。摘要中含代码不自动升级；工具自称完整提取不能独自证明完整。只有直接正文但完整性未知时保留4—5候选范围与待定，不强打4分。获取目标须在读取前明确，不能事后缩小成恰好返回的段落。复合返回如完整正文加摘要按正文证据判定；整份返回为摘要且含原文片段仍属3分。M3评内容是否详尽，M4评版本；不借答案质量判断获取状态。不同独立文档等权平均，保留原始均值；重试不重复计入，未知项不能删除后平均。'
            d['own']='五档是本研究按获取表示和完整性定义的有序量规，不是假定已知整页覆盖率。正文抽取文献支持区分正文与模板；不直接验证这五个等级，也不保证摘要总比截断正文信息少。'
        if k=='M8':d['action']='保留此前C=S+F及五档，失败请求只按一次实际调用计数，不另罚。程序记录并强制相同预算；保存耗时及可得的token。C=0或异常中断不自动给高分。调用数不是完整计算成本。'
        if k in {'M2','M8'}:d['boundary']=d['action']
        if k=='M6':d['refs']=['IQ','FACT','RUBRIC']
        if k=='M7':d['refs']=['SELF','FACT','RUBRIC']
        if k=='M10':d['name']='操作可执行性';d['change']='拟更名；按执行前所需补充或修改程度评分，运行状态另记'
        if k=='M4':d['action']+=' 评价对象是官方资料，不用最终答案是否定版给分。'
        if k=='M9':d['action']+=' 与M4区别：本项只看最终答案，官方资料清楚不代表答案已定版。'
        if k=='M11':
            d['refs']=['COMP'];d['change']='保留五档；新区间尚未确定，旧阈值只作历史对照'
            d['bands']=[]
            d['scale']='0–100连续分'
            d['change']='百分制：保留连续值，取消1—5分档及阈值'
            d['action']='本轮建议公式：各1—5分转为x=(s−1)/4；O=mean(x1,x2,x3)，T=mean(x5,x6)，P=x7；知识渠道指数K=(O+T+P)/3；M11=100×K×(0.7+0.3x4)×(0.9+0.1x8)。三个渠道等权，避免模型先验满分使其他渠道失去作用；版本与成本仍按原结构修正。M9/M10仍独立报告。正常低分1映射0，5映射1；已确认完全无可用官方正文时O=0、无第三方来源时T=0，不将受阻的M3伪造为1分。真正未知或不适用不能自动补0，综合分待定。原始精度保留，展示一位小数，不转五档，不解释为答对概率。这一改动明确把原来的“任一渠道兜底”汇总改成“三渠道总体支持”汇总；强渠道仍可帮助回答，但不能使其他渠道的缺口消失。'
            d['own']='OECD/JRC综合指标手册提供归一化、等权聚合及敏感性审查的方法依据，不规定本研究公式。选择三渠道等权是缺乏可信差异权重时的透明约定；0.7/0.3与0.9/0.1沿用历史权重，仍属研究约定而非经验估计。新旧公式不能混算。此公式是审阅稿，尚未写入Skill或重算历史结果。'
        d['boundary']=d['action']
    return metrics
